From 078ed91d75ba4dcb6d119aceb7f2e20ddc6ff698 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:35:35 +0100
Subject: [PATCH] applets/systemtray: keep long menus out of the panels

Qt doesn't know where the panels are on Wayland, so a long tray menu
was as tall as the whole screen and its first entries ended up above the
top edge. Limit the menu and its submenus to the space panels leave free.

BUG: 526183
---
 applets/systemtray/statusnotifieritemsource.cpp | 11 +++++++++++
 applets/systemtray/systemtray.cpp               |  9 ++++++---
 2 files changed, 17 insertions(+), 3 deletions(-)

diff --git a/applets/systemtray/statusnotifieritemsource.cpp b/applets/systemtray/statusnotifieritemsource.cpp
index eefedd6652..25cc082435 100644
--- a/applets/systemtray/statusnotifieritemsource.cpp
+++ b/applets/systemtray/statusnotifieritemsource.cpp
@@ -52,6 +52,17 @@ public:
     }

 protected:
+    QMenu *createMenu(QWidget *parent) override
+    {
+        QMenu *menu = DBusMenuImporter::createMenu(parent);
+        if (auto parentMenu = qobject_cast<QMenu *>(parent)) {
+            connect(menu, &QMenu::aboutToShow, menu, [menu, parentMenu] {
+                menu->setMaximumHeight(parentMenu->maximumHeight());
+            });
+        }
+        return menu;
+    }
+
     QIcon iconForName(const QString &name) override
     {
         return QIcon(new KIconEngine(name, m_iconLoader));
diff --git a/applets/systemtray/systemtray.cpp b/applets/systemtray/systemtray.cpp
index 4c1db7a2e7..3a16e53d79 100644
--- a/applets/systemtray/systemtray.cpp
+++ b/applets/systemtray/systemtray.cpp
@@ -40,7 +40,7 @@

 using namespace Qt::StringLiterals;

-static void showSystemTrayMenuWayland(QMenu *menu, QQuickItem *trayItem, Plasma::Types::Location location)
+static void showSystemTrayMenuWayland(QMenu *menu, QQuickItem *trayItem, Plasma::Types::Location location, int maximumHeight)
 {
     QWindow *trayWindow = trayItem->window();
     if (!trayWindow) {
@@ -100,6 +100,9 @@ static void showSystemTrayMenuWayland(QMenu *menu, QQuickItem *trayItem, Plasma:

     menuWindow->setTransientParent(trayWindow);

+    // Qt sizes long menus to the whole screen, as it doesn't know where the panels are
+    menu->setMaximumHeight(maximumHeight);
+
     menuWindow->setProperty("_q_waylandPopupAnchorRect", anchorRect);
     menuWindow->setProperty("_q_waylandPopupAnchor", QVariant::fromValue(anchor));
     menuWindow->setProperty("_q_waylandPopupGravity", QVariant::fromValue(gravity));
@@ -318,7 +321,7 @@ void SystemTray::showPlasmoidMenu(QQuickItem *appletInterface, int x, int y)

     KAcceleratorManager::manage(desktopMenu);

-    showSystemTrayMenuWayland(desktopMenu, appletInterface, location());
+    showSystemTrayMenuWayland(desktopMenu, appletInterface, location(), corona()->availableScreenRect(screen()).height());
 }

 QPointF SystemTray::popupPosition(QQuickItem *visualParent, int x, int y)
@@ -566,7 +569,7 @@ void SystemTray::openContextMenu(const QString &service, QPoint pos, QQuickItem
         [this, statusNotifierIcon = QPointer<QQuickItem>{statusNotifierIcon}](QMenu *menu) {
             if (statusNotifierIcon && menu && !menu->isEmpty()) {
                 KAcceleratorManager::manage(menu);
-                showSystemTrayMenuWayland(menu, statusNotifierIcon, location());
+                showSystemTrayMenuWayland(menu, statusNotifierIcon, location(), corona()->availableScreenRect(screen()).height());
             }
         },
         Qt::SingleShotConnection);
